import { useState } from 'react';
import { RefreshCw } from 'lucide-react';
import { useDebouncedValue, useResource } from '../hooks';
import { formatDate } from '../constants';
import { Button, Card, ErrorState, Field, Input, Loading, PageHeader, SearchBox, Table } from '../components/ui';
export default function AuditPage(){const[action,setAction]=useState('');const[actor,setActor]=useState('');const dAction=useDebouncedValue(action);const dActor=useDebouncedValue(actor);const r=useResource(()=>`/admin/audit?pageSize=200&action=${encodeURIComponent(dAction)}&actor=${encodeURIComponent(dActor)}`,[dAction,dActor]);if(r.initialLoading)return <Loading label="Loading audit trail…"/>;if(r.error)return <ErrorState message={r.error} onRetry={r.reload}/>;return <><PageHeader title="Immutable activity audit" description="Who changed what, when, from which request and device context." actions={<Button variant="secondary" icon={RefreshCw} onClick={r.reload}>Refresh</Button>}/><div className="bcrm-filterbar"><SearchBox value={action} onChange={setAction} busy={r.loading} label="Filter by audit action key" placeholder="Exact action key…"/><Field label="Actor user ID"><Input value={actor} onChange={e=>setActor(e.target.value)} placeholder="Optional exact ID"/></Field></div><Card className="flush" title={`${r.data?.total||0} audit events`} subtitle="Before and after snapshots remain server-side"><Table rows={r.data?.rows||[]} columns={[{key:'created_at',label:'Time',render:x=>formatDate(x.created_at,true)},{key:'action_key',label:'Action'},{key:'actor_user_id',label:'Actor'},{key:'actor_role',label:'Role'},{key:'entity_type',label:'Entity'},{key:'entity_id',label:'Record ID'},{key:'ip_address',label:'IP'},{key:'request_id',label:'Request ID'}]}/></Card></>}
