import { useState } from 'react';
import { Edit3, Plus, Save } from 'lucide-react';
import { crmApi, messageFromError } from '../api';
import { useDebouncedValue, useResource } from '../hooks';
import { formatDate } from '../constants';
import { Button, Card, ErrorState, Field, Input, Loading, Modal, PageHeader, SearchBox, Select, Status, Table, Textarea } from '../components/ui';
const blank={title:'',description:'',priority:'normal',status:'open',dueAt:'',assignedUserId:'',clientId:null,vendorId:null,saleId:null,version:1};
export default function Tasks(){const[status,setStatus]=useState('');const[mine,setMine]=useState(false);const[q,setQ]=useState('');const[form,setForm]=useState(null);const[error,setError]=useState('');const dq=useDebouncedValue(q);const r=useResource(()=>`/operations/tasks?status=${status}&mine=${mine?'1':'0'}&search=${encodeURIComponent(dq)}`,[status,mine,dq]);const edit=x=>setForm({id:x.id,title:x.title,description:x.description||'',priority:x.priority,status:x.status,dueAt:x.due_at?String(x.due_at).slice(0,16):'',assignedUserId:x.assigned_user_id||'',clientId:x.client_id||null,vendorId:x.vendor_id||null,saleId:x.sale_id||null,version:x.version});const save=async()=>{try{form.id?await crmApi.put(`/operations/tasks/${form.id}`,form):await crmApi.post('/operations/tasks',form);setForm(null);r.reload()}catch(e){setError(messageFromError(e))}};if(r.initialLoading)return <Loading/>;if(r.error)return <ErrorState message={r.error} onRetry={r.reload}/>;return <><PageHeader title="Tasks & follow-ups" description="Assign payment collection, renewal and vendor follow-up work with due dates and priorities." actions={<Button icon={Plus} onClick={()=>setForm(blank)}>New task</Button>}/>{error&&<div className="bcrm-banner warning">{error}</div>}<div className="bcrm-filterbar"><Field label="Status"><Select value={status} onChange={e=>setStatus(e.target.value)}><option value="">Open board</option><option value="open">Open</option><option value="in_progress">In progress</option><option value="completed">Completed</option><option value="cancelled">Cancelled</option></Select></Field><label className="bcrm-check"><input type="checkbox" checked={mine} onChange={e=>setMine(e.target.checked)}/> Assigned to me</label><SearchBox value={q} onChange={setQ} busy={r.loading} placeholder="Task, client, vendor or invoice…"/></div><Card className="flush" title={`${r.data?.rows?.length||0} tasks`}><Table rows={r.data?.rows||[]} columns={[{key:'title',label:'Task'},{key:'priority',label:'Priority',render:x=><Status tone={x.priority==='urgent'?'danger':x.priority==='high'?'warning':'info'}>{x.priority}</Status>},{key:'due_at',label:'Due',render:x=>formatDate(x.due_at,true)},{key:'client_name',label:'Client'},{key:'vendor_name',label:'Vendor'},{key:'status',label:'Status',render:x=><Status tone={x.status==='completed'?'success':'neutral'}>{x.status}</Status>},{key:'actions',label:'',render:x=><Button variant="secondary" icon={Edit3} onClick={()=>edit(x)}>Edit</Button>}]} /></Card><Modal open={Boolean(form)} title={form?.id?'Edit task':'New task'} onClose={()=>setForm(null)} footer={<><Button variant="secondary" onClick={()=>setForm(null)}>Cancel</Button><Button icon={Save} onClick={save}>Save task</Button></>}>{form&&<div className="bcrm-form"><Field label="Title"><Input value={form.title} onChange={e=>setForm({...form,title:e.target.value})}/></Field><Field label="Description"><Textarea value={form.description} onChange={e=>setForm({...form,description:e.target.value})}/></Field><div className="bcrm-form-grid"><Field label="Priority"><Select value={form.priority} onChange={e=>setForm({...form,priority:e.target.value})}><option value="low">Low</option><option value="normal">Normal</option><option value="high">High</option><option value="urgent">Urgent</option></Select></Field><Field label="Status"><Select value={form.status} onChange={e=>setForm({...form,status:e.target.value})}><option value="open">Open</option><option value="in_progress">In progress</option><option value="completed">Completed</option><option value="cancelled">Cancelled</option></Select></Field><Field label="Due date and time"><Input type="datetime-local" value={form.dueAt} onChange={e=>setForm({...form,dueAt:e.target.value})}/></Field><Field label="Assigned user ID" hint="Leave blank for unassigned"><Input value={form.assignedUserId} onChange={e=>setForm({...form,assignedUserId:e.target.value})}/></Field></div></div>}</Modal></>}
